        userId: docPheDuyetUserId,
        fullName: info?.fullName || "",
        chucVu: info?.chucVu || "",
        hasSignature: info?.hasSignature || false,
      }
    }
    return map
  }, [docId, docSteps, docPheDuyetUserId, signerInfoById, roles])

